INSERT INTO monster VALUES (320,'Dragon, True','Silver Dragon, Juvenile',NULL,'Large','Dragon','Cold','16d12+48 (152 hp)','+4','40 ft., fly 150 ft. (poor)','24 (-1 size, +15 natural), touch 9, flat-footed 24','+16','+24','Bite +20 (2d6+4) melee','Bite +20 (2d6+4) melee, 2 Claws +20 (1d8+2) melee, 2 Wings +19 (1d6+2) melee, Tail Slap +19 (1d8+6) melee','10 ft.','5 ft. (10 ft. with bite)','Breath weapon (40 ft. cone of paralyzing gas or 40 ft. cone of cold 8d8, DC 21)','Alternate form, blindsense 60 ft., cloudwalking, darkvision 120 ft., feather fall, immunity to acid and cold, immunity to sleep and paralysis, keen senses, spells (caster level 3rd), vulnerability to fire','Fort +13, Ref +10, Will +14','Str 19, Dex 10, Con 17, Int 18, Wis 19, Cha 18','Bluff +15, Concentration +15, Diplomacy +16, Disguise +15, Escape Artist +12, Intimidate +16, Jump +15, Knowledge (any 2) +23, Listen +25, Search +23, Sense Motive +16, Spot +25, Use Magic Device +15',NULL,'Alertness, Hover, Improved Initiative, Power Attack, Weapon Focus (bite), Weapon Focus (claw)',NULL,'Temperate mountains','Solitary or clutch (2-5)','10','Triple standard','Always lawful good','17-18 HD (Large)','-','Alternate Form (Su), Blindsense (Ex), Breath Weapon (Su), Cloudwalking (Su), Crush (Ex), Frightful Presence (Ex), Immunities (Ex), Keen Senses (Ex), Spell Resistance (Ex), Tail Sweep (Ex)','Juvenile silver dragon; CR 10; Large dragon (cold); HD 16d12+48; hp 152; Init +4; Spd 40 ft., fly 150 ft. (poor); AC 24 (-1 size, +15 natural), touch 9, flat-footed 24; Base Atk +16; Grp +24; Atk +20 melee (2d6+4, bite); Full Atk +20 melee (2d6+4, bite) and +20 melee (1d8+2, 2 claws) and +19 melee (1d6+2, 2 wings) and +19 melee (1d8+6, tail slap); Space/Reach 10 ft./5 ft. (10 ft. with bite); SA Breath weapon (40 ft. cone of paralyzing gas or 40 ft. cone of cold 8d8, DC 21); SQ Alternate form, blindsense 60 ft., cloudwalking, darkvision 120 ft., feather fall, immunity to acid and cold, immunity to sleep and paralysis, keen senses, spells (caster level 3rd), vulnerability to fire; AL LG; SV Fort +13, Ref +10, Will +14; Str 19, Dex 10, Con 17, Int 18, Wis 19, Cha 18\n\nSkills and Feats: Bluff +15, Concentration +15, Diplomacy +16, Disguise +15, Escape Artist +12, Intimidate +16, Jump +15, Knowledge (any 2) +23, Listen +25, Search +23, Sense Motive +16, Spot +25, Use Magic Device +15; Alertness, Hover, Improved Initiative, Power Attack, Weapon Focus (bite), Weapon Focus (claw)','\n      <div topic=\"Silver Dragon\" level=\"4\"><p><h4>Silver Dragon</h4></p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td/><td><b>Silver Dragon, Juvenile</b><br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td/><td>Large Dragon (Cold)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Hit Dice:</b><br/></td><td>16d12+48 (152 hp)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Initiative:</b><br/></td><td>+4<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Speed:</b><br/></td><td>40 ft., fly 150 ft. (poor)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Armor Class:</b><br/></td><td>24 (-1 size, +15 natural), touch 9, flat-footed 24<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Base Attack/Grapple:</b><br/></td><td>+16/+24<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Attack:</b><br/></td><td>Bite +20 (2d6+4) melee<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Full Attack:</b><br/></td><td>Bite +20 (2d6+4) melee, 2 Claws +20 (1d8+2) melee, 2 Wings +19 (1d6+2) melee, Tail Slap +19 (1d8+6) melee<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Space/Reach:</b><br/></td><td>10 ft./5 ft. (10 ft. with bite)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Special Attacks:</b><br/></td><td>Breath weapon (40 ft. cone of paralyzing gas or 40 ft. cone of cold 8d8, DC 21)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Special Qualities:</b><br/></td><td>Alternate form, blindsense 60 ft., cloudwalking, darkvision 120 ft., <i>feather fall</i>, immunity to acid and cold, immunity to sleep and paralysis, keen senses, spells (caster level 3rd), vulnerability to fire<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Saves:</b><br/></td><td>Fort +13, Ref +10, Will +14<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Abilities:</b><br/></td><td>Str 19, Dex 10, Con 17, Int 18, Wis 19, Cha 18<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Skills:</b><br/></td><td>Bluff +15, Concentration +15, Diplomacy +16, Disguise +15, Escape Artist +12, Intimidate +16, Jump +15, Knowledge (any 2) +23, Listen +25, Search +23, Sense Motive +16, Spot +25, Use Magic Device +15<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Feats:</b><br/></td><td>Alertness, Hover, Improved Initiative, Power Attack, Weapon Focus (bite), Weapon Focus (claw)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Environment:</b><br/></td><td>Temperate mountains<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Organization:</b><br/></td><td>Solitary or clutch (2-5)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Challenge Rating:</b><br/></td><td>10<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Treasure:</b><br/></td><td>Triple standard<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Alignment:</b><br/></td><td>Always lawful good<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Advancement:</b><br/></td><td>17-18 HD (Large)<br/></td></tr>\n<tr maxcol=\"3\" curcol=\"3\"><td><b>Level Adjustment:</b><br/></td><td>-<br/></td></tr>\n\n</table><p/><p/><p/><div topic=\"Dragon\" level=\"8\"><p><b>Dragon (Cold)</b></p>\n</div><div topic=\"Environment\" level=\"8\"><p><b>Environment:</b> Temperate mountains</p>\n</div><div topic=\"Organization\" level=\"8\"><p><b>Organization:</b> Wyrmling, very young, young, juvenile, and young adult: solitary or clutch (2-5); adult, mature adult, old, very old, ancient, wyrm, or great wyrm: solitary, pair, or family (1-2 and 2-5 offspring)</p>\n</div><div topic=\"Challenge Ratings\" level=\"8\"><p><b>Challenge Ratings:</b> Wyrmling 4; very young 5; young 7; juvenile 10; young adult 13; adult 15; mature adult 18; old 20; very old 21; ancient 23; wyrm 24; great wyrm 26</p>\n</div><div topic=\"Treasure\" level=\"8\"><p><b>Treasure:</b> Triple standard</p>\n</div><div topic=\"Alignment\" level=\"8\"><p><b>Alignment:</b> Always lawful good</p>\n</div><div topic=\"Advancement\" level=\"8\"><p><b>Advancement:</b> Wyrmling 8-9 HD; very young 11-12 HD; young 14-15 HD; juvenile 17-18 HD; young adult 20-21 HD; adult 23-24 HD; mature adult 26-27 HD; old 29-30 HD; very old 32-33 HD; ancient 35-36 HD; wyrm 38-39 HD; great wyrm 41+ HD</p>\n</div><div topic=\"Level Adjustment\" level=\"8\"><p><b>Level Adjustment:</b> Wyrmling +4; very young +4; young +5; others -</p><p/>\n</div><div topic=\"Silver Dragons by Age\" level=\"5\"><p><h5>Silver Dragons by Age</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"17\" curcol=\"17\">\n<td><b>Age</b><br/></td>\n<td><b>Size</b><br/></td>\n<td><b>Hit Dice (hp)</b><br/></td>\n<td><b>Str</b><br/></td>\n<td><b>Dex</b><br/></td>\n<td><b>Con</b><br/></td>\n<td><b>Int</b><br/></td>\n<td><b>Wis</b><br/></td>\n<td><b>Cha</b><br/></td>\n<td><b>Base Attack/</b><br/>\n<b>Grapple</b><br/></td> <td><b>Attack</b><br/></td>\n<td><b>Fort Save</b><br/></td>\n<td><b>Ref Save</b><br/></td>\n<td><b>Will Save</b><br/></td>\n<td><b>Breath Weapon (DC)</b><br/></td>\n<td><b>Frightful Presence DC</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"17\" curcol=\"17\">\n<td>Wyrmling<br/></td>\n<td>S<br/></td>\n<td>7d12+7 (52)<br/></td>\n<td>13<br/></td>\n<td>10<br/></td>\n<td>13<br/></td>\n<td>14<br/></td>\n<td>15<br/></td>\n<td>14<br/></td>\n<td>+7/+4<br/></td>\n<td>+9<br/></td>\n<td>+6<br/></td>\n<td>+5<br/></td>\n<td>+7<br/></td>\n<td>2d8 (14)<br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"17\" curcol=\"17\">\n<td>Very y